<script lang="ts">import type { ReviewDocument, Swap } from './types'; let { changes, swaps }: { changes: NonNullable<ReviewDocument['top_changes']>; swaps: Swap[] } = $props();</script>
<section class="priorities" aria-label="Top three changes"><div class="section-intro"><h2>Start with these three</h2><p>{changes.why_these_first}</p></div><ol>{#each changes.swap_ids as id, i}{@const swap = swaps.find(s => s.id === id)}<li><a href={'#swap-' + id}><span class="priority-number">0{i+1}</span>{#if swap}<span><span class="eyebrow">Cut → Add</span><span class="priority-cut card-name">{swap.cut.name}</span><strong class="card-name">{swap.add.name}</strong></span>{:else}<span>Swap unavailable: {id}</span>{/if}<span aria-hidden="true">↗</span></a></li>{/each}</ol></section>
